  }
}
function assert(cond, msg) {
  if (!cond) throw new Error(msg || "assertion failed");
}

Settings.throwOnInvalid = true;

check("2016-01-01/2016-12-31 does not throw, valid, default zone", () => {
  const i = Interval.fromISO("2016-01-01/2016-12-31");
  assert(i.isValid, "not valid");
  assert(i.start.zoneName === Settings.defaultZone.name, `zoneName ${i.start.zoneName} !== ${Settings.defaultZone.name}`);
});

check("2016-01-01/P1Y does not throw and is valid", () => {
